; fill.asm -- chapter 31: OUT (C),A in a row
; generated by gen31.py
        INCLUDE "msx.inc"
        OUTPUT "fill.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
sent    EQU VARS                ; the blocks sent
per     EQU VARS + 1            ; the blocks after each paper, on this machine
src     EQU VARS + 2            ; the next block's bytes
; The shapes cleared with the display off by OUT (C),A in a row, 14 T-states a
; byte; then after every paper the colours painted $14, dark blue paper, 8
; blocks at 60 Hz and 14 at 50 Hz.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $FF          ; colours  $2000, three sets
        VDP_REG 4, $03          ; shapes   $0000, three sets
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $1800        ; the names: 0 to 255 in each third
        ld e, 3
.names: xor a
.name:  out (VDP_DATA), a
        inc a
        jr nz, .name
        dec e
        jr nz, .names
        VRAM_WRITE $0000        ; the shapes: all paper
        xor a
        ld e, 24
        call fill
        VRAM_WRITE $2000        ; the colours: black on white
        ld a, $1F
        ld e, 24
        call fill
        xor a
        ld (sent), a
        ld hl, picture
        ld (src), hl
c0:     VRAM_WRITE $0000        ; the shapes, all paper, again
        xor a
        ld e, 48
.clr:   call out128
        dec e
        jr nz, .clr
c1:     ld a, ($002B)           ; bit 7 is 1 on a 50 Hz machine (chapter 4)
        rla
        ld a, 8                 ; blocks after the paper at 60 Hz ...
        jr nc, .sixty
        ld a, 14                ; ... and at 50 Hz
.sixty: ld (per), a
        VDP_REG 1, $C0          ; the display on
        in a, (VDP_CTRL)        ; F cleared: the first wait ends with a paper
loop:   call frame              ; the end of the paper
m0:     ld a, (per)
        ld e, a
        call paint              ; the blocks that fit before the next paper
m1:
s1:     ld a, (sent)
        cp 48
        jr nz, loop
done:   jr done

; frame: wait for the end of the paper: F, bit 7 of the status, read with the
; interrupts off (chapter 19)
frame:  in a, (VDP_CTRL)
        rla
        jr nc, frame
        ret

; place: the VDP's address, for writing, of block A of the picture: A x 128,
; and $800 more for the colours, from block 48: $2000 and not $1800
place:  ld d, a
        rrca
        and $80                 ; bit 0 of A, x 128: the low byte
        out (VDP_CTRL), a
        ld a, d
        srl a                   ; A / 2: the high byte
        cp 24
        jr c, .shapes
        add a, 8                ; the colours
.shapes: or $40
        out (VDP_CTRL), a
        ret

; fill: E blocks of 256 bytes of A to the VDP, after an address is set
fill:   ld b, 0
.out:   out (VDP_DATA), a
        djnz .out
        dec e
        jr nz, .out
        ret

; paint: up to E blocks of the colours painted $14, from block (sent) on
paint:  ld a, (sent)
        add a, 48               ; the colours' blocks are 48 to 95
        call place
.block: ld a, (sent)
        cp 48
        ret z                   ; all painted
        ld a, $14
        call out128
        ld hl, sent
        inc (hl)
        dec e
        jr nz, .block
        ret

; out128: 128 bytes of A with OUT (C),A in a row, 14 T-states a byte, the
; same byte every time: after the paper, or with the display off
out128: ld c, VDP_DATA
        out (c), a
        out (c), a
        out (c), a
        out (c), a
        out (c), a
        out (c), a
        out (c), a
        out (c), a
        out (c), a
